<?php $pageTitle='Products';$subtitle='Add, edit, stock-control and retire every product from one place.';$active='Products';require __DIR__.'/_layout.php';$pdo=db();$products=$pdo->query('SELECT * FROM products ORDER BY id DESC')->fetchAll();$cats=['Solar Battery','Battery','E-Rickshaw Lithium Battery','Cooler','AC','Chimney','Solar Panel','Home Inverter','High Capacity Inverter','3-Phase High Capacity Inverter','Grid Inverter','Hybrid Inverter','3-Phase Hybrid Inverter','3-Phase Lift Inverter','Solar Inverter','Washing Machine','Refrigerator','Room Heater','Accessory'];
function pv($p,$k){return ae($p[$k]??'');}
?>
<div class="card"><div class="section-head"><div><h2>Product catalogue</h2><span style="color:var(--muted)"><?=count($products)?> records</span></div><div class="actions"><a class="btn blue" href="import.php">Import / Scan</a><button class="btn primary" id="addProduct">Add Product</button></div></div><div class="filters"><input class="input" id="search" placeholder="Search name, brand, PID, barcode, CAT No..." oninput="filterRows()"></div><div class="table-wrap"><table id="productTable"><thead><tr><th>Product</th><th>Brand / Category</th><th>PID / Barcode</th><th>Price</th><th>Stock</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($products as $p):?><tr data-search="<?=ae(strtolower($p['name'].' '.$p['brand'].' '.$p['product_pid'].' '.$p['barcode'].' '.$p['cat_no']))?>"><td><div style="display:flex;gap:10px;align-items:center"><img class="thumb" src="<?=ae($p['image_url']?:'../data/Swarnim Logo.png')?>" onerror="this.src='../data/Swarnim Logo.png'"><div><strong><?=pv($p,'name')?></strong><br><small><?=pv($p,'model_name')?> · <?=pv($p,'sku')?></small></div></div></td><td><?=pv($p,'brand')?><br><span class="pill blue"><?=pv($p,'category')?></span></td><td><?=pv($p,'product_pid')?><br><small><?=pv($p,'barcode')?></small></td><td><strong>₹<?=number_format((float)$p['selling_price'],2)?></strong><br><small>MRP ₹<?=number_format((float)$p['mrp'],2)?></small></td><td><?=number_format((int)$p['stock'])?><br><span class="pill <?=in_array($p['stock_status'],['in_stock','low_stock'])?'green':'red'?>"><?=ae(str_replace('_',' ',$p['stock_status']))?></span></td><td><span class="pill <?=($p['status']==='active'?'green':'red')?>"><?=ae($p['status'])?></span></td><td><div class="actions"><button class="btn" onclick='editProduct(<?=json_encode($p,JSON_HEX_TAG|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_HEX_AMP)?>)'>Edit</button><button class="btn danger" onclick="deleteProduct(<?=$p['id']?>)">Delete</button></div></td></tr><?php endforeach;if(!$products):?><tr><td colspan="7" class="empty">No products found.</td></tr><?php endif;?></tbody></table></div></div>
<div class="modal" id="productModal"><div class="modal-box"><div class="modal-head"><h2 id="modalTitle">Add Product</h2><button class="close" onclick="closeModal()">×</button></div><form id="productForm" enctype="multipart/form-data"><input type="hidden" name="id" id="pid"><div class="form-grid">
<?php $fields=[['name','Product Name',1],['brand','Brand'],['model_name','Model Name'],['product_pid','Product ID / P-ID'],['barcode','Barcode'],['item','Item'],['cat_no','CAT No.'],['product_size','Product Size'],['color_finish','Color / Finish'],['net_quantity','Net Quantity'],['mrp','MRP'],['selling_price','Selling Price'],['old_price','Old Price'],['discount_percent','Discount %'],['you_save','You Save'],['stock','Stock'],['rating','Rating'],['reviews','Reviews'],['badge','Badge'],['tagline','Tagline'],['short_description','Short Description'],['voltage','Voltage'],['manufactured_on','Manufactured On'],['maximum_suction','Maximum Suction'],['net_weight','Net Weight'],['net_contents','Net Contents'],['sku','SKU']];foreach($fields as $f):$type=($f[0]==='manufactured_on'?'date':(in_array($f[0],['mrp','selling_price','old_price','discount_percent','you_save','rating'],true)?'number':($f[0]==='stock'||$f[0]==='reviews'?'number':'text')));?><div class="field"><label><?=ae($f[1])?></label><input class="input" id="f_<?=$f[0]?>" name="<?=$f[0]?>" type="<?=$type?>" <?=in_array($f[0],['mrp','selling_price','old_price','discount_percent','you_save','rating'],true)?'step="0.01"':''?>></div><?php endforeach;?><div class="field"><label>Stock Status</label><select class="select" id="f_stock_status" name="stock_status"><option value="in_stock">In Stock</option><option value="low_stock">Low Stock</option><option value="out_of_stock">Out of Stock</option><option value="preorder">Preorder</option></select></div><div class="field"><label>Status</label><select class="select" id="f_status" name="status"><option value="active">Active</option><option value="inactive">Inactive</option><option value="draft">Draft</option></select></div><div class="field full"><label>Category</label><select class="select" id="f_category" name="category"><?php foreach($cats as $c):?><option><?=ae($c)?></option><?php endforeach;?></select></div><div class="field full"><label>Product Image URL</label><input class="input" id="f_image_url" name="image_url"></div><div class="field"><label>Upload Product Image</label><input class="input" type="file" name="image" accept="image/jpeg,image/png,image/webp"></div><div class="field"><label>Featured</label><label class="check"><input type="checkbox" id="f_featured" name="featured" value="1"> Show as featured</label></div><div class="field full"><label>Description</label><textarea class="textarea" id="f_description" name="description" rows="4"></textarea></div><div class="field"><label>Key Features</label><textarea class="textarea" id="f_key_features" name="key_features" rows="5" placeholder="One feature per line or JSON"></textarea></div><div class="field"><label>Specifications</label><textarea class="textarea" id="f_specifications" name="specifications" rows="5" placeholder="Capacity: 150Ah&#10;Warranty: 60 Months"></textarea></div></div><div class="actions" style="margin-top:18px"><button class="btn primary" type="submit">Save Product</button><button class="btn" type="button" onclick="closeModal()">Cancel</button></div></form></div></div>
<script>const modal=document.querySelector('#productModal');const form=document.querySelector('#productForm');function openModal(){modal.classList.add('open')}function closeModal(){modal.classList.remove('open');form.reset();document.querySelector('#pid').value='';document.querySelector('#modalTitle').textContent='Add Product'}document.querySelector('#addProduct').onclick=openModal;function editProduct(p){openModal();document.querySelector('#modalTitle').textContent='Edit Product';for(const k of ['name','brand','category','model_name','product_pid','barcode','item','cat_no','product_size','color_finish','net_quantity','mrp','selling_price','old_price','discount_percent','you_save','stock','rating','reviews','badge','tagline','short_description','voltage','manufactured_on','maximum_suction','net_weight','net_contents','sku','stock_status','status','image_url','description']){const e=document.querySelector('#f_'+k);if(e)e.value=p[k]??''}document.querySelector('#pid').value=p.id;document.querySelector('#f_featured').checked=!!Number(p.featured);document.querySelector('#f_key_features').value=typeof p.key_features==='string'?p.key_features:JSON.stringify(p.key_features||{},null,2);document.querySelector('#f_specifications').value=typeof p.specifications==='string'?p.specifications:JSON.stringify(p.specifications||{},null,2)}form.addEventListener('submit',async e=>{e.preventDefault();const fd=new FormData(form);fd.append('action','save-product');const r=await fetch('api.php',{method:'POST',body:fd,headers:{'X-CSRF-Token':CSRF}});const j=await r.json();toast(j.message,j.ok);if(j.ok)setTimeout(()=>location.reload(),700)});async function deleteProduct(id){if(!confirm('Delete this product? Existing order history will keep its snapshot.'))return;const j=await api('delete-product',{id});toast(j.message,j.ok);if(j.ok)setTimeout(()=>location.reload(),500)}function filterRows(){const q=document.querySelector('#search').value.toLowerCase();document.querySelectorAll('#productTable tbody tr').forEach(r=>r.style.display=(r.dataset.search||'').includes(q)?'':'none')}</script><?php require __DIR__.'/_foot.php'; ?>
